def date(n,nullable=True):return F(n,'date',nullable,format='yyyy-MM-dd HH:mm:ss')
def aux(prefix):return [F(prefix+'_batch',nullable=False),date(prefix+'_loaded',False),D(prefix+'_ledger'),F(prefix+'_unused'),F(prefix+'_note'),F(prefix+'_row','long',False)]
def row(fields,**values):
 r={f['name']:(None if f['nullable']=='true' else {'string':'','long':0,'integer':0,'boolean':False,'decimal':'0.00','date':'2026-01-01 00:00:00'}[f['type']]) for f in fields};r.update(values);return r
def rows(fields,items):
 result=[]
 for i,x in enumerate(items):
  r=row(fields,**x)
  for f in fields:
   n=f['name']
   if n.endswith('_row') and n not in x:r[n]=i+1
   if n.endswith('_unused') and n not in x:r[n]='opaque-'+str(i)
   if n.endswith('_ledger') and n not in x:r[n]='17.25'
   if n.endswith('_batch') and n not in x:r[n]='batch-'+n
  result.append(r)
 return result
def expected(records,indices,updates):
 # Indices and every business result are explicitly hand-authored below. Only unchanged copying is shared.
 return [dict(records[i],**u) for i,u in zip(indices,updates)]
def pack(tid,arch,component,title,intro,clauses,fields,out,code,fixture,checks=None,settings=None,resources=None,action='replaced',traps=None):
 checks=checks or [(c,'The corresponding business obligation is observable in the supplied output record.',[i+1]) for i,c in enumerate(clauses)]
 checks=[('Uses the component entry contract and destinations correctly; equivalent supported CTL forms accepted.','The configured component determines invocation and routing.',[1])]+checks
 return make(tid,arch,component,title,intro,clauses,[('Input'+tid,fields)],out,code,checks,[('Must not silently discard an input that the business contract requires to emit.','Lost source rows defeat reconciliation.'),('Must not dereference null or parse malformed text before the applicable validation.','Dirty source values have defined business outcomes.'),('Must not reuse state or reference attributes from a previous unrelated record.','Decisions must reflect the current source and stated continuity rules.')],fixture,settings=settings,resources=resources,change={'action':action,'reason':intro},traps=traps)


